-- Q1 [Cofactors, Coenzymes & Vitamins] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Cofactors, Coenzymes & Vitamins', 'A biochemist purifies an enzyme that has no catalytic activity on its own but becomes fully active only once its required organic coenzyme binds within the protein. The fully assembled, cofactor-bound form of this enzyme is best described as which of the following?', '[{"label": "A", "text": "Holoenzyme"}, {"label": "B", "text": "Apoenzyme"}, {"label": "C", "text": "Prosthetic group"}, {"label": "D", "text": "Zymogen"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because LibreTexts states that ''enzymes bound with their required cofactors are called holoenzymes,'' which is exactly the fully assembled, cofactor-bound, catalytically active form described in the stem. The textbook defines cofactors as ''molecules that bind to enzymes and are required for catalytic activity,'' and notes that coenzymes are ''small organic molecules that are often derived from vitamins,'' so an enzyme that gains activity only after its coenzyme binds is, in its active state, a holoenzyme. (Choice A) is correct: a holoenzyme is the enzyme together with its bound required cofactor, the form that is catalytically active. (Choice B) is incorrect: an apoenzyme is the opposite state, because LibreTexts says ''enzymes not yet associated with a required cofactor are called apoenzymes,'' so the apoenzyme is the inactive, cofactor-free form rather than the assembled active one. (Choice C) is incorrect: a prosthetic group is the tightly bound cofactor itself, not the enzyme-plus-cofactor complex, since the text states that ''tight-binding coenzymes are referred to as prosthetic groups.'' (Choice D) is incorrect: a zymogen is unrelated to cofactor binding, because LibreTexts defines it as ''an inactive precursor of an enzyme'' that is activated by a covalent change such as proteolysis, not by binding a coenzyme. This is a Knowledge of Scientific Concepts and Principles question because you must recall the textbook definition that distinguishes a holoenzyme (enzyme plus bound cofactor) from an apoenzyme, a prosthetic group, and a zymogen.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 45)
  RETURNING id
)
