-- Q4 [Cofactors, Coenzymes & Vitamins] medium skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Cofactors, Coenzymes & Vitamins', 'A patient with a thiamine (vitamin B1) deficiency has reduced activity of pyruvate dehydrogenase because the enzyme can no longer bind thiamine pyrophosphate (TPP), the small vitamin-derived organic molecule it needs for catalysis. TPP is best classified as which of the following?', '[{"label": "A", "text": "A metal ion cofactor"}, {"label": "B", "text": "An apoenzyme"}, {"label": "C", "text": "A holoenzyme"}, {"label": "D", "text": "A coenzyme"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because thiamine pyrophosphate (TPP) is a small organic molecule derived from a vitamin (thiamine, vitamin B1), which is exactly how LibreTexts defines a coenzyme. The textbook states that "Coenzymes are small organic molecules that are often derived from vitamins" and that "TPP is a derivative of thiamine, vitamin B1." Because TPP is the non-protein, vitamin-derived organic helper that the enzyme needs for catalysis, it is properly classified as a coenzyme; without it the protein is an inactive apoenzyme. (Choice A) is incorrect: a metal ion cofactor is the other major class of cofactor, comprising metals such as "iron, magnesium, manganese, cobalt, copper, zinc, and molybdenum," whereas TPP is an organic, vitamin-derived molecule rather than a metal ion. (Choice B) is incorrect: an apoenzyme is the protein enzyme itself when it is "not yet associated with a required cofactor," not the cofactor; TPP is the helper that converts the apoenzyme into a functional holoenzyme. (Choice C) is incorrect: a holoenzyme is the complete "enzyme bound with [its] required cofactors," i.e., the whole protein-plus-cofactor complex, so it cannot describe TPP, which is only the cofactor portion. (Choice D) is correct: TPP is a small organic, vitamin-derived molecule, which is the textbook definition of a coenzyme. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definition of a coenzyme and the cofactor/apoenzyme/holoenzyme terminology that classifies a vitamin-derived molecule such as TPP.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
