-- Q6 [Cofactors, Coenzymes & Vitamins] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Cofactors, Coenzymes & Vitamins', 'A researcher purifies an enzyme and finds that extensive dialysis, which removes small dissolved molecules, abolishes its catalytic activity; adding back a small, vitamin-derived organic molecule fully restores activity. The inactive protein remaining after dialysis is best described as which of the following?', '[{"label": "A", "text": "A holoenzyme"}, {"label": "B", "text": "An apoenzyme"}, {"label": "C", "text": "A prosthetic group"}, {"label": "D", "text": "A zymogen"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because the molecule removed by dialysis is a loosely bound, vitamin-derived coenzyme: the textbook states that "Coenzymes are small organic molecules that are often derived from vitamins" and that they "can bind loosely with the enzyme and be released from the active site" (LibreTexts 32722-32723). A protein that has lost its required cofactor is, by definition, the inactive form: "Enzymes not yet associated with a required cofactor are called apoenzymes, whereas enzymes bound with their required cofactors are called holoenzymes" (LibreTexts 32727-32728). Restoring activity by simply adding the cofactor back, rather than by cleaving the protein, confirms the protein is intact but cofactor-free, which is the apoenzyme state (LibreTexts 32740-32741). (Choice A) is the reverse: a holoenzyme is the enzyme WITH its cofactor bound, i.e., the active form before dialysis, not the inactive protein left behind (LibreTexts 32728). (Choice B) is correct: the dialyzed, cofactor-free, inactive protein is the apoenzyme, which regains activity only when the required coenzyme is restored (LibreTexts 32727-32728, 32740-32741). (Choice C) names the cofactor, not the protein, and also describes the wrong binding mode: a prosthetic group is the TIGHTLY bound coenzyme that "cannot dissociate easily," whereas this coenzyme washed out during dialysis because it was loosely bound (LibreTexts 32722-32727). (Choice D) is an inactive precursor activated by proteolytic cleavage, not by re-adding a cofactor: zymogens are "synthesized as inactive precursors (zymogens) that become activated on limited proteolysis," which does not match restoration by a small dialyzable molecule (LibreTexts 21380-21381). This is a Scientific Reasoning and Problem Solving question because you must apply the apoenzyme/holoenzyme definitions and the loosely-bound-coenzyme concept to interpret what the dialysis-and-restoration experiment reveals about the protein''s state.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 75)
  RETURNING id
)
