-- Q7 [Cofactors, Coenzymes & Vitamins] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Cofactors, Coenzymes & Vitamins', 'While characterizing a newly isolated dehydrogenase, a biochemist finds that the enzyme remains continuously active over many turnovers without ever needing a separate regeneration step on the enzyme itself: in each cycle a small organic cofactor enters the active site, is reduced as the substrate is oxidized, and then diffuses away as a product that is re-oxidized elsewhere in the cell before binding again. The cofactor showing this behavior is most likely which of the following?', '[{"label": "A", "text": "Thiamine pyrophosphate (TPP)"}, {"label": "B", "text": "Flavin adenine dinucleotide (FAD)"}, {"label": "C", "text": "Nicotinamide adenine dinucleotide (\\(\\text{NAD}^+\\))"}, {"label": "D", "text": "Heme"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because the diagnostic behavior described—a cofactor that binds, is reduced as the substrate is oxidized, then dissociates as a product and is regenerated elsewhere in the cell rather than on the enzyme—is the hallmark of a loosely bound coenzyme, which the textbook says "can bind loosely with the enzyme and be released from the active site... they are also considered substrates for the reaction" (LibreTexts Biochemistry, lines 32722-32723). \(\text{NAD}^+\) and \(\text{NADP}^+\) are exactly this case: they are "used as dissociable substrates/cofactors" and "the free enzyme is continually active since the \(\text{NAD}^+\)... cofactor binds (as a substrate) and dissociates (as a product) after each catalytic cycle" (lines 32926-32928). (Choice A) is wrong because thiamine pyrophosphate "is covalently attached to the enzyme, such as in pyruvate dehydrogenase" (line 32825), so it never dissociates as a freely diffusing product. (Choice B) is a partial-truth trap: FAD is also regenerated each turnover, but the textbook specifies it is "tightly or covalently attached to an enzyme, so FAD must be regenerated in each catalytic cycle" (lines 32881-32882)—it is re-oxidized in place on the enzyme and does not diffuse away as a product, which is the very feature the stem requires. (Choice C) is correct: a small organic cofactor that binds as a substrate, is reduced, and dissociates as a product to be re-oxidized elsewhere is a loosely bound coenzyme, and \(\text{NAD}^+\) is the textbook''s prototypical dissociable, continually recycled example (lines 32722-32723, 32926-32928). (Choice D) is wrong because heme is a tightly bound prosthetic group—"tight-binding coenzymes are referred to as prosthetic groups" and heme is held in place by "interactions with histidine residues" (lines 32727, 32729-32731)—so it stays coordinated to the enzyme rather than diffusing off as a product. This is a Scientific Reasoning and Problem Solving question because you must apply the distinction between loosely bound (dissociable) coenzymes and tightly bound prosthetic groups to a described catalytic cycle and identify the cofactor whose binding behavior matches the dissociate-and-recycle pattern.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 140)
  RETURNING id
)
