-- Q11 [Michaelis-Menten Kinetics (Vmax, Km, Saturation)] medium skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Michaelis-Menten Kinetics (Vmax, Km, Saturation)', 'A researcher characterizing a newly purified enzyme measures initial reaction velocity across a range of substrate concentrations and reports the single substrate concentration at which the enzyme operates at exactly half of its maximal velocity. This reported value most directly corresponds to which kinetic parameter?', '[{"label": "A", "text": "The turnover number, \\(k_{cat}\\)"}, {"label": "B", "text": "The maximal velocity, \\(V_{max}\\)"}, {"label": "C", "text": "The Michaelis constant, \\(K_m\\)"}, {"label": "D", "text": "The specificity constant, \\(k_{cat}/K_m\\)"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because the Michaelis constant, \(K_m\), is operationally defined as the substrate concentration at which the initial velocity equals half of \(V_{max}\). The textbook states that \(K_m\) "is operationally defined as the substrate concentration at which the initial velocity is half of VM" (lines 27363-27364) and likewise that "v = VM2, when S = KM" (line 27092). Because \(K_m\) has units of molarity, it is the only listed parameter that is itself a substrate concentration, which is exactly what the researcher measured. (Choice A) is incorrect: \(k_{cat}\), the turnover number, is "the catalytic rate constant, with units of s-1" that measures how many bound substrate molecules form product per second (lines 27366-27367), not a substrate concentration. (Choice B) is incorrect: \(V_{max}\) is the maximal velocity itself, the rate approached "when S >> KM" (line 27089), so it is a velocity rather than the half-maximal substrate concentration. (Choice C) is correct: \(K_m\) is, by definition, the substrate concentration giving an initial velocity of \(V_{max}/2\) (lines 27363-27364, 27092). (Choice D) is incorrect: \(k_{cat}/K_m\) is the specificity constant, "a biomolecular rate constant... with units of M-1s-1" (lines 27368-27371), which is a second-order rate constant, not a substrate concentration. This is a Knowledge of Scientific Concepts and Principles question because you must recall the operational definition of the Michaelis constant \(K_m\) as the substrate concentration yielding half-maximal velocity and distinguish it from the other named kinetic constants.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 60)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', 'confusing a rate constant for a concentration parameter' FROM q
  UNION ALL
  SELECT id, 'B', 'reversed_relationship', 'swapping the velocity axis (Vmax) for the concentration axis (Km)' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'confusing the specificity (efficiency) constant for the half-saturation concentration' FROM q;

-- Q12 [Michaelis-Menten Kinetics (Vmax, Km, Saturation)] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Michaelis-Menten Kinetics (Vmax, Km, Saturation)', 'A researcher assays a purified enzyme at a substrate concentration roughly 100 times its \(K_m\), so the measured initial velocity is essentially equal to \(V_{max}\). Hoping to raise the assay''s maximum velocity, the researcher considers several single changes to the reaction. Which change is most likely to increase \(V_{max}\)?', '[{"label": "A", "text": "Adding a large excess of additional substrate to the reaction"}, {"label": "B", "text": "Adding a competitive inhibitor that binds the active site"}, {"label": "C", "text": "Switching to a substrate with a smaller \\(K_m\\) for the enzyme"}, {"label": "D", "text": "Adding more copies of the same purified enzyme to the reaction"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because \(V_{max}\) is set by how much enzyme is present, not by how much substrate is added once the enzyme is already saturated. LibreTexts states that under steady-state conditions "Vmax=kcatE0," meaning the maximum velocity is the product of the turnover number \(k_{cat}\) and the total enzyme concentration \([E]_0\), so adding more enzyme is the change that raises \(V_{max}\). At a substrate concentration about 100 times \(K_m\) the enzyme is effectively saturated, and the text notes that "v = Vmax (or VM) when S is much greater than Ks," so the velocity is already at its ceiling for that amount of enzyme. (Choice A) is incorrect: because the enzyme is already saturated near \(V_{max}\), adding more substrate cannot push the rate above \(V_{max}\)—the text emphasizes that "only if S >> KS ... will saturation be achieved," and the system has already reached that plateau. (Choice B) is incorrect: a competitive inhibitor changes only the apparent \(K_m\), not the maximum velocity, since the plot shows "different fixed concentrations of inhibitor ... each with the same VM, but with different apparent KM values." (Choice C) is incorrect: \(K_m\) is "the substrate concentration at which the initial velocity is half of VM" and does not determine \(V_{max}\); at saturation the velocity equals \(V_{max}=k_{cat}[E]_0\) regardless of the substrate''s \(K_m\). (Choice D) is correct: because "Vmax=kcatE0," increasing the total amount of the same enzyme proportionally increases \(V_{max}\), which is the only listed change that raises the maximum velocity. This is a Scientific Reasoning and Problem Solving question because you must apply the Michaelis-Menten relationship \(V_{max}=k_{cat}[E]_0\) and the saturation behavior of the velocity curve to reason that, with the enzyme already at \(V_{max}\), only adding more enzyme can raise the maximum rate.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 90)
  RETURNING id
)
