-- Q21 [Catalytic Efficiency (kcat and kcat/Km)] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Catalytic Efficiency (kcat and kcat/Km)', 'A pre-med student reviews the kinetic parameters of a purified enzyme and focuses on its reported \(k_{cat}\), also called the turnover number. This value is best described as the number of:', '[{"label": "A", "text": "substrate molecules a single enzyme active site converts to product each second"}, {"label": "B", "text": "competing substrates the enzyme can distinguish between each second"}, {"label": "C", "text": "substrate molecules bound by the enzyme each second at half-maximal velocity"}, {"label": "D", "text": "enzyme-substrate collisions that occur each second at the diffusion limit"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because \(k_{cat}\), the catalytic rate constant, is the turnover number: it counts how many bound substrate molecules are converted to product per enzyme active site each second. LibreTexts states that "kcat: The catalytic rate constant, with units of s-1, is often called the turnover number. It is a measure of how many bound substrate molecules ''turnover'' or form product in 1 second," as is evident from \(v_0 = k_{cat}[ES]\). Because \(k_{cat}\) is a per-second count of catalytic cycles for the enzyme working at saturation, choice A captures its meaning exactly. (Choice A) is correct: \(k_{cat}\) is the turnover number, the number of substrate molecules an active site converts to product each second. (Choice B) is wrong because differentiating between two competing substrates is the role of the specificity constant \(k_{cat}/K_m\), which LibreTexts says "describes how well an enzyme can differentiate between two different and competing substrates," not the meaning of \(k_{cat}\) alone. (Choice C) is wrong because the substrate concentration at half-maximal velocity defines \(K_m\), the Michaelis constant (''operationally defined as the substrate concentration at which the initial velocity is half of VM''), a molarity, not a per-second turnover count. (Choice D) is wrong because counting enzyme-substrate collisions at the diffusion limit describes a diffusion-controlled \(k_{cat}/K_m\) (around \(10^8\) M\(^{-1}\)s\(^{-1}\), where ''the reaction is essentially done as soon as the enzyme and substrate collide''), not the turnover number \(k_{cat}\) itself. This is a Knowledge of Scientific Concepts and Principles question because you must recall that \(k_{cat}\), the turnover number, is the number of substrate molecules converted to product per active site per second.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 70)
  RETURNING id
)
