-- Q25 [Catalytic Efficiency (kcat and kcat/Km)] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Catalytic Efficiency (kcat and kcat/Km)', 'A researcher compares two enzymes acting on the same substrate at equal enzyme concentrations. Enzyme P has \(k_{cat}=1000\ \text{s}^{-1}\) and \(K_m=1\ \text{mM}\) (so \(k_{cat}/K_m=1.0\times10^{6}\ \text{M}^{-1}\text{s}^{-1}\)), whereas enzyme Q has \(k_{cat}=200\ \text{s}^{-1}\) and \(K_m=0.01\ \text{mM}\) (so \(k_{cat}/K_m=2.0\times10^{7}\ \text{M}^{-1}\text{s}^{-1}\)). If the assay is run at a saturating substrate concentration far above both \(K_m\) values, which enzyme would most likely convert substrate to product faster?', '[{"label": "A", "text": "Enzyme Q, because it has the higher \\(k_{cat}/K_m\\)"}, {"label": "B", "text": "Enzyme Q, because it has the lower \\(K_m\\)"}, {"label": "C", "text": "Both convert substrate at equal rates, because at saturation the velocity no longer depends on the enzyme''s kinetic constants"}, {"label": "D", "text": "Enzyme P, because it has the higher \\(k_{cat}\\)"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because at a substrate concentration far above both \(K_m\) values the reaction is saturated, and the textbook states that "when S >> KM, v = VM = k3E0" — that is, the velocity approaches \(V_{max}=k_{cat}[E_0]\) and becomes "zero order with respect to S and first order in E" (line 27089). Because "VM = kcatE0" for all reactions (line 27225) and the two enzymes are present at equal concentration, the enzyme with the higher \(k_{cat}\) — the turnover number, "a measure of how many bound substrate molecules ''turnover'' or form product in 1 second" (line 27366) — turns substrate over faster. Enzyme P (\(k_{cat}=1000\ \text{s}^{-1}\)) exceeds enzyme Q (\(k_{cat}=200\ \text{s}^{-1}\)), so P wins at saturation despite having the lower \(k_{cat}/K_m\). (Choice A) is wrong because \(k_{cat}/K_m\) governs the rate only "Under condition when [S] << KM," where "the Michaelis-Menten equation becomes v0 = (kcat/KM)[E0][S]" (line 27368); at the saturating [S] in this scenario that low-[S] regime does not apply, so Q''s higher specificity constant does not make it faster. (Choice B) is wrong because \(K_m\) is "the substrate concentration at which the initial velocity is half of VM" (line 27363); once [S] is far above both \(K_m\) values both enzymes are near \(V_{max}=k_{cat}[E_0]\), so the lower \(K_m\) of Q confers no rate advantage at saturation. (Choice C) is wrong because at saturation the velocity still depends on a kinetic constant: "VM = kcatE0" (line 27225), so it scales directly with \(k_{cat}\) rather than becoming equal for the two enzymes. (Choice D) is correct: at saturating [S] the velocity approaches \(V_{max}=k_{cat}[E_0]\) (lines 27089, 27225), and with equal [E] the enzyme with the higher \(k_{cat}\) — enzyme P — converts substrate faster. This is a Scientific Reasoning and Problem Solving question because you must apply the regime dependence of enzyme kinetics, recognizing that \(k_{cat}/K_m\) governs the rate at low [S] while \(k_{cat}\) governs the rate at saturation, and use the given numbers to determine which enzyme is faster under saturating conditions.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'partial_truth', 'kcat/Km trap (true only at low [S])' FROM q
  UNION ALL
  SELECT id, 'B', 'adjacent_fact', 'Km as affinity confused with rate at saturation' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'saturation means kinetics no longer matter' FROM q;
